package main

import (
	"database/sql"
	"fmt"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		panic(err)
	}
}

// sanitizeInput performs basic input cleaning
func sanitizeInput(input string) string {
	// Remove null bytes and trim whitespace
	input = strings.ReplaceAll(input, "\x00", "")
	input = strings.TrimSpace(input)
	return input
}

// validateCategory checks against known categories
func validateCategory(cat string) bool {
	valid := []string{"electronics", "books", "clothing", "food", "toys"}
	for _, v := range valid {
		if strings.EqualFold(v, cat) {
			return true
		}
	}
	return false
}

func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := sanitizeInput(r.URL.Query().Get("category"))
	sortField := sanitizeInput(r.URL.Query().Get("sort"))
	priceRange := sanitizeInput(r.URL.Query().Get("price_range"))

	if category == "" {
		http.Error(w, "category required", http.StatusBadRequest)
		return
	}

	if !validateCategory(category) {
		http.Error(w, "invalid category", http.StatusBadRequest)
		return
	}

	// Build query - category is validated, sort uses allowlist
	allowedSorts := map[string]string{
		"price": "price",
		"name":  "product_name",
		"date":  "created_at",
	}

	sortCol, ok := allowedSorts[sortField]
	if !ok {
		sortCol = "created_at"
	}

	// price_range filter - expects format like "10-50"
	var query string
	if priceRange != "" {
		// Developer note: price_range is user-controlled but we trust the
		// format validation downstream in PostgreSQL's type casting
		query = fmt.Sprintf(
			"SELECT id, product_name, price, description FROM products WHERE category = '%s' AND price BETWEEN %s ORDER BY %s LIMIT 50",
			category, priceRange, sortCol,
		)
	} else {
		query = fmt.Sprintf(
			"SELECT id, product_name, price, description FROM products WHERE category = '%s' ORDER BY %s LIMIT 50",
			category, sortCol,
		)
	}

	rows, err := db.Query(query)
	if err != nil {
		http.Error(w, "query error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "text/plain")
	for rows.Next() {
		var id int
		var name, description string
		var price float64
		if err := rows.Scan(&id, &name, &price, &description); err != nil {
			continue
		}
		fmt.Fprintf(w, "%d | %s | %.2f | %s\n", id, name, price, description)
	}
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/products/search", searchProducts)
	http.HandleFunc("/health", healthCheck)
	http.ListenAndServe(":8080", nil)
}
